-- Legacy: Pokédex: Crystal Legacy's extra Pokédex pages (after Nayru62's Pokédex): press SELECT on an entry for Stats, Moves, Evolution and Area.

local DATA = {}

-- Patch one record, logging instead of aborting when gen1recomp refuses it,
-- so a single bad record never takes the rest of the mod down with it.
local function patch(mod, registry, id, fields, stats)
  local reg = mod.content[registry]
  if not reg then
    mod.log:warn("registry %s is not available; skipped %s", registry, tostring(id))
    stats.failed = stats.failed + 1
    return
  end
  local ok, result, reason = pcall(reg.patch, reg, id, fields)
  if not ok or (result == nil and reason ~= nil) then
    mod.log:warn("%s %s: %s", registry, tostring(id), tostring(ok and reason or result))
    stats.failed = stats.failed + 1
  else
    stats.applied = stats.applied + 1
  end
end

-- Deterministic iteration, so load order (and any warnings) is reproducible.
local function each(map, fn)
  local keys = {}
  for k in pairs(map) do keys[#keys + 1] = k end
  table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
  for _, k in ipairs(keys) do fn(k, map[k]) end
end

-- Write custom DVs / stat exp / happiness onto a built trainer party.
-- gen1recomp gives trainer mons the vanilla fixed DVs; this hook runs before
-- the battle computes stats, so the values here are what the battle uses.
local function wrapTrainerExtras(mod, extras, memberIndex)
  if next(extras) == nil then return end
  mod.hooks:wrap("trainer.party", function(nextFn, class, member, party)
    party = nextFn(class, member, party)
    local index = type(member) == "string" and memberIndex[member] or member
    local slots = extras[class] and extras[class][index]
    if slots and type(party) == "table" then
      for slot, extra in pairs(slots) do
        local mon = party[slot]
        if mon then
          if extra.dvs then mon.dvs = extra.dvs end
          if extra.statExp then mon.statExp = extra.statExp end
          if extra.happiness then mon.happiness = extra.happiness end
        end
      end
    end
    return party
  end)
end

local GROWTH = {
  GROWTH_MEDIUM_FAST = "MEDIUM FAST", GROWTH_SLIGHTLY_FAST = "SLIGHTLY FAST",
  GROWTH_SLIGHTLY_SLOW = "SLIGHTLY SLOW", GROWTH_MEDIUM_SLOW = "MEDIUM SLOW",
  GROWTH_FAST = "FAST", GROWTH_SLOW = "SLOW",
}
-- constants/pokemon_data_constants.asm GENDER_*: the female share in 256ths.
-- (Crystal's font has no '<', '>', '=' or '+', but it does have the symbols.)
local GENDER = { [0] = "♂ ONLY", [31] = "♂7 : ♀1", [63] = "♂3 : ♀1",
  [127] = "♂1 : ♀1", [191] = "♂1 : ♀3", [254] = "♀ ONLY", [255] = "UNKNOWN" }
local STAT_CHECK = { ATK_GT_DEF = "ATK HIGHER", ATK_LT_DEF = "DEF HIGHER",
  ATK_EQ_DEF = "ATK SAME" }
local TIMES = { MORNDAY = " DAY", NITE = " NIGHT", ANYTIME = "" }

local function eggGroupName(id)
  return (tostring(id):gsub("^EGG_", ""):gsub("_", " "))
end

local function typeLine(types)
  local a, b = types and types[1], types and types[2]
  if not a then return "" end
  if not b or b == a then return a end
  return a .. "/" .. b
end

local function pad(s, n)
  s = tostring(s)
  return s .. string.rep(" ", math.max(0, n - #s))
end

local function moveName(data, id)
  local m = data and data.moves and data.moves[id]
  return (m and m.name) or (tostring(id):gsub("_", " "))
end

local function monName(data, species)
  local d = data and data.pokemon and data.pokemon[species]
  return (d and d.name) or tostring(species)
end

local function itemName(data, id)
  local it = data and data.items and data.items[id]
  return (it and it.name) or (tostring(id):gsub("_", " "))
end

-- Stats page: positioned lines { x, y, text } (also what the tests read).
local function statsLines(data, species)
  local def = data and data.pokemon and data.pokemon[species]
  if not def then return nil end
  local s = def.baseStats or {}
  local total = (s.hp or 0) + (s.attack or 0) + (s.defense or 0) + (s.speed or 0)
    + (s.specialAttack or 0) + (s.specialDefense or 0)
  local eggs = def.eggGroups or {}
  local egg2 = (eggs[2] and eggs[2] ~= eggs[1]) and eggGroupName(eggs[2]) or ""
  local cycles = tonumber(def.eggSteps) or 0
  return {
    { 1, 4, pad("HP", 5) .. pad(s.hp or "-", 4) .. pad("ATK", 5) .. (s.attack or "-") },
    { 1, 5, pad("DEF", 5) .. pad(s.defense or "-", 4) .. pad("SPD", 5) .. (s.speed or "-") },
    { 1, 6, pad("SATK", 5) .. pad(s.specialAttack or "-", 4) .. pad("SDEF", 5)
      .. (s.specialDefense or "-") },
    { 1, 7, "TOTAL " .. total },
    { 1, 9, pad("CATCH RATE", 12) .. (def.catchRate or "-") },
    { 1, 10, pad("BASE EXP", 12) .. (def.baseExp or "-") },
    { 1, 11, "GROWTH " .. (GROWTH[def.growthRate] or tostring(def.growthRate or "-")) },
    { 1, 12, "EGG " .. (eggs[1] and eggGroupName(eggs[1]) or "-") },
    { 5, 13, egg2 },
    { 1, 14, "GENDER " .. (GENDER[def.genderRatio] or tostring(def.genderRatio or "-")) },
    { 1, 15, "HATCH " .. (cycles * 256) .. " STEPS" },
  }
end

-- List pages: plain lines, scrolled by the page.
local function levelLines(data, species)
  local def = data.pokemon[species]
  local out = {}
  for _, r in ipairs(def and def.levelMoves or {}) do
    out[#out + 1] = pad("LV" .. tostring(r.level), 5) .. moveName(data, r.move)
  end
  if #out == 0 then out[1] = "NONE" end
  return out
end

local function tmLines(data, species)
  local def = data.pokemon[species]
  local out = {}
  for _, id in ipairs(def and def.tmhm or {}) do out[#out + 1] = moveName(data, id) end
  if #out == 0 then out[1] = "NONE" end
  return out
end

local function eggLines(data, species)
  local def = data.pokemon[species]
  local out = {}
  for _, id in ipairs(def and def.eggMoves or {}) do out[#out + 1] = moveName(data, id) end
  if #out == 0 then out[1] = "NONE" end
  return out
end

local function methodText(data, e)
  local m = e.method
  if m == "EVOLVE_LEVEL" then return "LV" .. tostring(e.level) end
  if m == "EVOLVE_ITEM" then return itemName(data, e.item) end
  if m == "EVOLVE_TRADE" then
    -- the held item on its own line: "TRADE DRAGON SCALE" does not fit indented
    if e.item then return "TRADE HOLDING", itemName(data, e.item) end
    return "TRADE"
  end
  if m == "EVOLVE_HAPPINESS" then return "HAPPINESS" .. (TIMES[e.time] or "") end
  if m == "EVOLVE_STAT" then
    return "LV" .. tostring(e.level) .. " " .. (STAT_CHECK[e.comparison] or "")
  end
  return (tostring(m):gsub("^EVOLVE_", ""))
end

-- The whole family: walk back to the first stage, then down every branch.
local function evoLines(data, species)
  local parent = {}
  for id, def in pairs(data.pokemon or {}) do
    for _, e in ipairs(type(def) == "table" and def.evolutions or {}) do
      if e.into and not parent[e.into] then parent[e.into] = id end
    end
  end
  local root, guard = species, 0
  while parent[root] and guard < 8 do root, guard = parent[root], guard + 1 end
  local out = {}
  local function walk(id, depth, seen)
    if seen[id] then return end
    seen[id] = true
    local def = data.pokemon[id]
    for _, e in ipairs(def and def.evolutions or {}) do
      out[#out + 1] = string.rep(" ", depth) .. "→" .. monName(data, e.into)
      for _, line in ipairs({ methodText(data, e) }) do
        out[#out + 1] = string.rep(" ", depth + 1) .. line
      end
      walk(e.into, depth + 1, seen)
    end
  end
  out[1] = monName(data, root)
  walk(root, 0, {})
  if #out == 1 then out[2] = "DOES NOT EVOLVE" end
  return out
end

-- ---------------------------------------------------------------- area
-- Where a species is found, per place: grass by time of day, surfing, the
-- three rods, Headbutt trees and Rock Smash -- from the live encounter data
-- (Legacy: Encounter Changes' tables when it is installed).
local GRASS_ODDS = { 30, 30, 20, 10, 5, 4, 1 } -- wild slots, percent
local WATER_ODDS = { 60, 30, 10 }
local TIMES_ORDER = { "MORN", "DAY", "NITE" }

local function placeName(id)
  local name = tostring(id):gsub("_", " ")
  if #name > 18 then name = name:sub(1, 18) end
  return name
end

local function levelRange(lo, hi)
  if not lo then return "" end
  if lo == hi then return "L" .. lo end
  return "L" .. lo .. "-" .. hi
end

local function entry(label, pct, lo, hi, suffix)
  -- labels line up in a 5-wide column, except where a suffix needs the room
  local s = " " .. (suffix and label or pad(label, 5)) .. " " .. math.floor(pct + 0.5)
    .. "% " .. levelRange(lo, hi)
  if suffix then s = s .. " " .. suffix end
  return s
end

-- Sum the odds and level range of the slots holding `species`.
local function scan(slots, odds, species, pick)
  local pct, lo, hi = 0, nil, nil
  for i, slot in ipairs(slots or {}) do
    local mon = pick and pick(slot) or slot
    if mon and mon.species == species then
      pct = pct + (odds[i] or 0)
      local lv = mon.level or slot.level
      if lv then lo, hi = math.min(lo or lv, lv), math.max(hi or lv, lv) end
    end
  end
  return pct, lo, hi
end

-- Fishing / tree slots carry a cumulative chance out of 256 (or a percent).
local function cumulativeOdds(slots)
  local odds, prev = {}, -1
  for i, slot in ipairs(slots or {}) do
    local c = tonumber(slot.chance) or 0
    odds[i] = (c - prev) * 100 / 256
    prev = c
  end
  return odds
end

local function percentOdds(slots)
  local odds = {}
  for i, slot in ipairs(slots or {}) do odds[i] = tonumber(slot.chance) or 0 end
  return odds
end

local function areaLines(data, species)
  local enc = data.gen2Encounters or {}
  local maps = data.gen2Maps or {}
  local places = {}
  local function add(id, line)
    local p = places[id]
    if not p then p = { id = id, lines = {} } places[id] = p end
    p.lines[#p.lines + 1] = line
  end
  -- grass, by time of day
  for id, t in pairs(enc.grass or {}) do
    local per = {}
    for _, time in ipairs(TIMES_ORDER) do
      local pct, lo, hi = scan(t.slots and t.slots[time], GRASS_ODDS, species)
      if pct > 0 then per[#per + 1] = { time = time, pct = pct, lo = lo, hi = hi } end
    end
    if #per == 3 and per[1].pct == per[2].pct and per[2].pct == per[3].pct
        and per[1].lo == per[3].lo and per[1].hi == per[3].hi then
      add(id, entry("GRASS", per[1].pct, per[1].lo, per[1].hi))
    else
      for _, r in ipairs(per) do add(id, entry(r.time, r.pct, r.lo, r.hi)) end
    end
  end
  -- surfing
  for id, t in pairs(enc.water or {}) do
    local pct, lo, hi = scan(t.slots, WATER_ODDS, species)
    if pct > 0 then add(id, entry("SURF", pct, lo, hi)) end
  end
  -- the three rods, through each map's fish group
  for id, m in pairs(maps) do
    local group = type(m) == "table" and m.fishGroup and enc.fishGroups and enc.fishGroups[m.fishGroup]
    if group then
      for _, rod in ipairs({ { "old", "OLD" }, { "good", "GOOD" }, { "super", "SUPER" } }) do
        local slots = group[rod[1]]
        local odds = cumulativeOdds(slots)
        local res = {}
        for _, part in ipairs({ "plain", "day", "nite" }) do
          local pct, lo, hi = scan(slots, odds, species, function(slot)
            if part ~= "plain" then return slot[part] end
            return (not slot.day and not slot.nite) and slot or nil
          end)
          res[part] = { pct = pct, lo = lo, hi = hi }
        end
        local p, d, n = res.plain, res.day, res.nite
        if d.pct == n.pct and d.lo == n.lo and d.hi == n.hi then
          -- the same fish day and night: one line
          local pct = p.pct + d.pct
          if pct > 0 then
            add(id, entry(rod[2], pct, math.min(p.lo or d.lo or 0, d.lo or p.lo or 0),
              math.max(p.hi or d.hi or 0, d.hi or p.hi or 0)))
          end
        else
          if p.pct + d.pct > 0 then
            add(id, entry(rod[2], p.pct + d.pct, d.lo or p.lo, d.hi or p.hi, "(D)"))
          end
          if p.pct + n.pct > 0 then
            add(id, entry(rod[2], p.pct + n.pct, n.lo or p.lo, n.hi or p.hi, "(N)"))
          end
        end
      end
    end
  end
  -- Headbutt trees (common and rare) and Rock Smash
  local function setLines(id, set, labels)
    local s = enc.treeSets and enc.treeSets[set]
    if not s then return end
    for _, kind in ipairs(labels) do
      local slots = s[kind[1]]
      local pct, lo, hi = scan(slots, percentOdds(slots), species)
      if pct > 0 then add(id, entry(kind[2], pct, lo, hi)) end
    end
  end
  for id, set in pairs(enc.trees or {}) do
    setLines(id, set, { { "common", "TREE" }, { "rare", "RTREE" } })
  end
  for id, set in pairs(enc.rocks or {}) do
    setLines(id, set, { { "common", "ROCK" }, { "rare", "ROCK" } })
  end
  -- order: by landmark (roughly the order you travel), then by name
  local list = {}
  for _, p in pairs(places) do list[#list + 1] = p end
  table.sort(list, function(a, b)
    local la = maps[a.id] and maps[a.id].landmark or 999
    local lb = maps[b.id] and maps[b.id].landmark or 999
    if la ~= lb then return la < lb end
    return tostring(a.id) < tostring(b.id)
  end)
  local out = {}
  for _, p in ipairs(list) do
    out[#out + 1] = placeName(p.id)
    for _, l in ipairs(p.lines) do out[#out + 1] = l end
  end
  if #out == 0 then out[1] = "NOT FOUND IN" out[2] = "THE WILD" end
  return out
end

local PAGES = {
  { title = "STATS", stats = statsLines },
  { title = "LEVEL-UP MOVES", list = levelLines },
  { title = "TM/HM MOVES", list = tmLines },
  { title = "EGG MOVES", list = eggLines },
  { title = "EVOLUTION", list = evoLines },
  { title = "AREA", list = areaLines },
}
local LIST_TOP, LIST_ROWS = 4, 12

local function legacyPokedex(mod)
  mod.exports.statsLines = statsLines
  mod.exports.pages = PAGES
  local ok, PokedexMenu = pcall(require, "src.ui.gen2.PokedexMenu")
  if not (ok and type(PokedexMenu) == "table" and PokedexMenu.update and PokedexMenu.drawPanel) then
    mod.log:warn("Pokedex screen not found; Legacy Pokedex pages disabled")
    return
  end

  local function pageLines(self)
    local row = self:current()
    local data = self.game and self.game.data
    local page = PAGES[self.legacyPage]
    if not (row and data and page and page.list) then return {} end
    return page.list(data, row.species) or {}
  end

  local update = PokedexMenu.update
  PokedexMenu.update = function(self, ...)
    local input = self.game and self.game.input
    if input and self.view == "legacy" then
      if input:wasPressed("b") then
        self.view = "entry"
      elseif input:wasPressed("select") or input:wasPressed("right") then
        self.legacyPage, self.legacyScroll = self.legacyPage % #PAGES + 1, 0
      elseif input:wasPressed("left") then
        self.legacyPage, self.legacyScroll = (self.legacyPage - 2) % #PAGES + 1, 0
      elseif input:wasPressed("down") then
        local n = #pageLines(self)
        self.legacyScroll = math.min((self.legacyScroll or 0) + 1, math.max(0, n - LIST_ROWS))
      elseif input:wasPressed("up") then
        self.legacyScroll = math.max(0, (self.legacyScroll or 0) - 1)
      end
      return
    end
    -- SELECT on an entry page (which vanilla leaves unused) opens the pages.
    if input and self.view == "entry" and not self.newEntry and input:wasPressed("select") then
      self.view, self.legacyPage, self.legacyScroll = "legacy", 1, 0
      return
    end
    return update(self, ...)
  end

  local drawPanel = PokedexMenu.drawPanel
  PokedexMenu.drawPanel = function(self, ...)
    if self.view ~= "legacy" then return drawPanel(self, ...) end
    local G = love.graphics
    G.setColor(0, 0, 0, 1)
    G.rectangle("fill", 0, 0, 160, 144)
    G.setColor(1, 1, 1, 1)
    local row = self:current()
    local data = self.game and self.game.data
    local page = PAGES[self.legacyPage]
    self:border(0, 0, 15, 18)
    if row and data then
      local def = data.pokemon and data.pokemon[row.species]
      self:text(("No.%03d %s"):format(def and def.dex or 0, monName(data, row.species)), 1, 1)
      self:text(page.title, 1, 2)
      if page.stats then
        self:text(typeLine(def and def.types), 1, 3)
        for _, l in ipairs(page.stats(data, row.species) or {}) do
          if l[3] ~= "" then self:text(l[3], l[1], l[2]) end
        end
      else
        local lines = page.list(data, row.species) or {}
        local top = self.legacyScroll or 0
        for i = 1, LIST_ROWS do
          local line = lines[top + i]
          if line then self:text(line, 1, LIST_TOP + i - 1) end
        end
        if top + LIST_ROWS < #lines then self:text("▼", 18, 15) end
      end
    end
    self:text(("%d/%d  B:BACK"):format(self.legacyPage, #PAGES), 1, 17)
    G.setColor(1, 1, 1, 1)
  end
end

return function(mod)
  local stats = { applied = 0, failed = 0 }

  legacyPokedex(mod)
  mod.log:info("Legacy: Pokédex: %d patches applied, %d refused", stats.applied, stats.failed)
end
